    /** 一条标签 / 档位 */
    internal class Entry(
        val groupIndex: Int,
        val groupName: String,
        val labelId: String,
        val labelName: String,
        val parentId: String,
        val parentName: String,
    ) {
        /** 界面上的那一行：有父标签时写成「量比1.5-2.0」，没有就只是标签名 */
        val display: String get() = if (parentName.isEmpty()) labelName else parentName + labelName
    }

    /** 全部条目，顺序就是宿主标签表的顺序 */
    val entries: List<Entry> by lazy {
        ArrayList<Entry>(1200).also { out ->
            for (line in CHUNKS.joinToString("").split('\n')) {
                if (line.isEmpty()) continue
                val f = line.split('\t')
                if (f.size < 6) continue
                out.add(Entry(f[0].toIntOrNull() ?: 0, f[1], f[2], f[3], f[4], f[5]))
            }
        }
    }

    /** labelId → 条目 */
    private val byId: Map<String, Entry> by lazy { entries.associateBy { it.labelId } }

    fun entryOf(labelId: String): Entry? = byId[labelId.trim()]

    /**
     * 标签的显示名：表体里的档位写「量比1.5-2.0」；父标签（本身不在表体、只有 [tree] 里那个节点）
     * 写它的名字「量比」；都不认识的退回 id 本身。
     */
    fun displayOf(labelId: String): String =
        byId[labelId.trim()]?.display ?: nodeOf(labelId)?.name ?: labelId

    /** [tree] 里按 labelId 找节点：父标签不是可选条件，只有这里面记着它的名字与档位 */
    private val nodesById: Map<String, LabelNode> by lazy {
        val m = HashMap<String, LabelNode>()
        for ((_, labels) in tree) for (n in labels) m[n.labelId] = n
        m
    }

    fun nodeOf(labelId: String): LabelNode? = nodesById[labelId.trim()]

    /** 这个标签的档位；不是父标签就返回空表（无档位的标签点了直接用） */
    fun bandsOf(labelId: String): List<Entry> = nodeOf(labelId)?.bands ?: emptyList()

    /**
     * 是不是「父标签」：自己不在表体里（不是一条可选条件），但 [tree] 里有它这个节点。
     *
     * 为什么要有这条判据：`label:<父labelId>` 这样的成员**接不了数** —— 实测宿主
     * createStrategy 返回 code=0、查成分股 0 只。所以「点一下就建成员」的成员是待细分状态，
     * 取数时直接跳过，界面上提示去 ⋮ 里选档。
     */
    fun isParentOf(labelId: String): Boolean {
        val id = labelId.trim()
        return id.isNotEmpty() && byId[id] == null && nodesById[id] != null
    }

    /** 这个标签属于哪个分组（技术指标 / 行情面 / …），成员副标题要用 */
    fun groupOf(labelId: String): String? {
        val id = labelId.trim()
        entryOf(id)?.let { return it.groupName }
        val node = nodeOf(id) ?: return null
        for ((name, labels) in tree) if (labels.any { it === node }) return name
        return null
    }

    /**
     * 界面用的一层：一个标签名 + 它自己的档位。
     *
     * [bands] 为空 = 这个标签没有档位，点了直接用；非空 = 点了还要在它下面选一档
     * （「量比」的 8 档、「创新高」的 7 档）。
     */
    internal class LabelNode(
        val labelId: String,
        val name: String,
        val bands: MutableList<Entry> = ArrayList(),
    ) {
        val hasBands: Boolean get() = bands.isNotEmpty()
    }

    /**
     * 两层结构：[(分组名, [标签...]), ...]。
     *
     * 表体只存了**档位**（父标签本身不是可选条件），所以父标签要在这里现建节点 ——
     * 顺序按首次出现排，与宿主「标签选股」面板的排列一致。
     */
    val tree: List<Pair<String, List<LabelNode>>> by lazy {
        val out = ArrayList<Pair<String, ArrayList<LabelNode>>>()
        for (e in entries) {
            if (out.isEmpty() || out.last().first != e.groupName) {
                out.add(e.groupName to ArrayList())
            }
            val group = out.last().second
            if (e.parentName.isEmpty()) {
                group.add(LabelNode(e.labelId, e.labelName))
                continue
            }
            val node = group.firstOrNull { it.labelId == e.parentId }
                ?: LabelNode(e.parentId, e.parentName).also { group.add(it) }
            node.bands.add(e)
        }
        out.map { it.first to (it.second as List<LabelNode>) }
    }


    /** 按分组切好：[(行情面, [...]) , ...]，顺序与宿主一致 */
    val groups: List<Pair<String, List<Entry>>> by lazy {
        val out = ArrayList<Pair<String, List<Entry>>>()
        for (e in entries) {
            if (out.isNotEmpty() && out.last().first == e.groupName) {
                (out.last().second as ArrayList<Entry>).add(e)
            } else {
                out.add(e.groupName to arrayListOf(e))
            }
        }
        out
    }
}
